    @Test
    void notFound_branches() throws Exception {
        mockMvc.perform(get("/api/equipment/nope/status"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value("EQUIPMENT_NOT_FOUND"));
