                        downtime.startAt(), downtime.endAt(), downtime.reason(),
                        downtime.deductionMinutes(), Downtime.STATUS_REVOKED,
                        downtime.createdAt(), now);
                return toDowntimeResponse(revoked, equipment.version() + 1);
            });
}

